export const getSceneMataFile = async (url: string): Promise<any> => {
  const requestFile = await fetch(url, {
    mode: 'cors',
    credentials: 'omit',
    cache: 'reload',
  });
  if (requestFile.status === 200) {
    const content = await requestFile.json();
    console.log('content', content);
    return content;
  }
};
export interface SceneMataFileResponse {
  // Define the structure of the response if known
  [key: string]: any;
}
